-- Checked article URLs and scoped citations; preserve previous provenance for audit.
ALTER TABLE cultural_rules ADD COLUMN original_source_name VARCHAR(255);
ALTER TABLE cultural_rules ADD COLUMN original_source_url TEXT;
ALTER TABLE cultural_rules ADD COLUMN source_verified BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE cultural_rules ADD COLUMN source_note TEXT;
UPDATE cultural_rules SET original_source_name=source_name, original_source_url=source_url;
ALTER TABLE cultural_knowledge ADD COLUMN original_content TEXT;
ALTER TABLE cultural_knowledge ADD COLUMN original_source_name VARCHAR(255);
ALTER TABLE cultural_knowledge ADD COLUMN original_source_url TEXT;
UPDATE cultural_knowledge SET original_content=content, original_source_name=source_name, original_source_url=source_url;
UPDATE cultural_rules SET source_name='Cục Du lịch Quốc gia Việt Nam – Vietnam Tourism – All about ao dai: Vietnam''s national dress',source_url='https://vietnam.travel/things-to-do/ao-dai-vietnam',source_note='Nguồn giới thiệu lịch sử và đặc trưng trang phục. Gợi ý phối đồ và điểm số là quy tắc tham khảo của ứng dụng, chưa được nguồn này xác nhận toàn bộ.',source_verified=FALSE WHERE outfit_id=(SELECT id FROM outfits WHERE code='AO_DAI');
UPDATE cultural_knowledge SET title='Lịch sử áo dài',content='Áo dài hiện đại phát triển từ áo ngũ thân. Trong thập niên 1930, họa sĩ Nguyễn Cát Tường (Le Mur) góp phần thay đổi phom áo theo hướng ôm dáng hơn.',source_name='Cục Du lịch Quốc gia Việt Nam – Vietnam Tourism – All about ao dai: Vietnam''s national dress',source_url='https://vietnam.travel/things-to-do/ao-dai-vietnam' WHERE outfit_id=(SELECT id FROM outfits WHERE code='AO_DAI') AND category='ORIGIN';
UPDATE cultural_knowledge SET title='Áo dài trong đời sống',content='Áo dài hiện diện trong học đường, lễ Tết, cưới hỏi và chụp ảnh. Sắc trắng thường gắn với hình ảnh nữ sinh; sắc đỏ thường được chọn dịp Tết và lễ cưới.',source_name='Cục Du lịch Quốc gia Việt Nam – Vietnam Tourism – All about ao dai: Vietnam''s national dress',source_url='https://vietnam.travel/things-to-do/ao-dai-vietnam' WHERE outfit_id=(SELECT id FROM outfits WHERE code='AO_DAI') AND category='MEANING';
UPDATE cultural_knowledge SET title='Cách mặc và biến thể',content='Áo dài thường mặc cùng quần. Các thiết kế đương đại có nhiều biến thể về chiều dài, tay áo và cổ áo, trong đó có cổ thuyền hoặc cổ tròn.',source_name='Cục Du lịch Quốc gia Việt Nam – Vietnam Tourism – All about ao dai: Vietnam''s national dress',source_url='https://vietnam.travel/things-to-do/ao-dai-vietnam' WHERE outfit_id=(SELECT id FROM outfits WHERE code='AO_DAI') AND category='CHARACTERISTICS';
UPDATE outfits SET origin='Áo dài hiện đại phát triển từ áo ngũ thân. Trong thập niên 1930, họa sĩ Nguyễn Cát Tường (Le Mur) góp phần thay đổi phom áo theo hướng ôm dáng hơn.',cultural_meaning='Áo dài hiện diện trong học đường, lễ Tết, cưới hỏi và chụp ảnh. Sắc trắng thường gắn với hình ảnh nữ sinh; sắc đỏ thường được chọn dịp Tết và lễ cưới.' WHERE code='AO_DAI';
UPDATE cultural_rules SET source_name='Hội LHPN tỉnh Khánh Hòa – nghiên cứu của Trịnh Bách – Nguồn gốc của Áo dài Việt Nam (phần 1)',source_url='https://hlhpn.khanhhoa.gov.vn/article/tin-tuc-su-kien/nguon-goc-cua-ao-dai-viet-nam-phan-1.html',source_note='Nguồn giới thiệu lịch sử và đặc trưng trang phục. Gợi ý phối đồ và điểm số là quy tắc tham khảo của ứng dụng, chưa được nguồn này xác nhận toàn bộ.',source_verified=FALSE WHERE outfit_id=(SELECT id FROM outfits WHERE code='AO_TU_THAN');
UPDATE cultural_knowledge SET title='Trang phục phụ nữ Bắc Bộ',content='Theo nghiên cứu của Trịnh Bách được Hội LHPN đăng tải, áo dài tứ thân từng gắn với phụ nữ nông thôn Bắc Bộ, thường mặc cùng yếm và váy.',source_name='Hội LHPN tỉnh Khánh Hòa – nghiên cứu của Trịnh Bách – Nguồn gốc của Áo dài Việt Nam (phần 1)',source_url='https://hlhpn.khanhhoa.gov.vn/article/tin-tuc-su-kien/nguon-goc-cua-ao-dai-viet-nam-phan-1.html' WHERE outfit_id=(SELECT id FROM outfits WHERE code='AO_TU_THAN') AND category='ORIGIN';
UPDATE cultural_knowledge SET title='Liên hệ với văn hóa Quan họ',content='Trang phục liền chị Quan họ có áo mớ ba, mớ bảy và nón thúng quai thao. Đây là bối cảnh văn hóa Kinh Bắc để tìm hiểu cách phối trang phục lễ hội.',source_name='Cục Di sản văn hóa – Dân ca Quan họ Bắc Ninh',source_url='https://dsvh.gov.vn/dan-ca-quan-ho-bac-ninh-482' WHERE outfit_id=(SELECT id FROM outfits WHERE code='AO_TU_THAN') AND category='MEANING';
UPDATE cultural_knowledge SET title='Thân áo và cách mặc',content='Áo tứ thân có bốn thân, mở ở giữa phía trước và không có khuy cài theo dạng được mô tả trong nghiên cứu. Vạt áo có thể thắt hoặc buông, giữ bằng dây lưng vải.',source_name='Hội LHPN tỉnh Khánh Hòa – nghiên cứu của Trịnh Bách – Nguồn gốc của Áo dài Việt Nam (phần 1)',source_url='https://hlhpn.khanhhoa.gov.vn/article/tin-tuc-su-kien/nguon-goc-cua-ao-dai-viet-nam-phan-1.html' WHERE outfit_id=(SELECT id FROM outfits WHERE code='AO_TU_THAN') AND category='CHARACTERISTICS';
UPDATE outfits SET origin='Theo nghiên cứu của Trịnh Bách được Hội LHPN đăng tải, áo dài tứ thân từng gắn với phụ nữ nông thôn Bắc Bộ, thường mặc cùng yếm và váy.',cultural_meaning='Trang phục liền chị Quan họ có áo mớ ba, mớ bảy và nón thúng quai thao. Đây là bối cảnh văn hóa Kinh Bắc để tìm hiểu cách phối trang phục lễ hội.' WHERE code='AO_TU_THAN';
UPDATE cultural_rules SET source_name='Cổng du lịch Huế – Sở Văn hóa, Thể thao và Du lịch – Tinh tế áo dài ngũ thân',source_url='https://visithue.vn/Tinh-te-ao-dai-ngu-than.html/?pid=MjA1MjR8Y3NkbGRs0',source_note='Nguồn giới thiệu lịch sử và đặc trưng trang phục. Gợi ý phối đồ và điểm số là quy tắc tham khảo của ứng dụng, chưa được nguồn này xác nhận toàn bộ.',source_verified=FALSE WHERE outfit_id=(SELECT id FROM outfits WHERE code='AO_NGU_THAN');
UPDATE cultural_knowledge SET title='Áo ngũ thân và Đàng Trong',content='Áo ngũ thân gắn với cải cách y phục của chúa Nguyễn Phúc Khoát năm 1744 tại Đàng Trong. Dưới thời Minh Mạng, trang phục được phổ biến trên phạm vi cả nước.',source_name='Sở Văn hóa, Thể thao và Du lịch thành phố Huế – Lễ đón nhận danh hiệu Di sản văn hóa phi vật thể quốc gia “Tri thức may, mặc Áo dài Huế”',source_url='https://svhttdl.hue.gov.vn/tin-trong-tinh/le-don-nhan-danh-hieu-di-san-van-hoa-phi-vat-the-quoc-gia-tri-thuc-may-mac-ao-dai-hue.html' WHERE outfit_id=(SELECT id FROM outfits WHERE code='AO_NGU_THAN') AND category='ORIGIN';
UPDATE cultural_knowledge SET title='Ý nghĩa được truyền lại',content='Theo nhà nghiên cứu Nguyễn Xuân Hoa, bốn thân chính được diễn giải tượng trưng cho cha mẹ hai bên, thân con cho người mặc. Năm khuy được liên hệ với ngũ thường và ngũ luân.',source_name='Cổng du lịch Huế – Sở Văn hóa, Thể thao và Du lịch – Tinh tế áo dài ngũ thân',source_url='https://visithue.vn/Tinh-te-ao-dai-ngu-than.html/?pid=MjA1MjR8Y3NkbGRs0' WHERE outfit_id=(SELECT id FROM outfits WHERE code='AO_NGU_THAN') AND category='MEANING';
UPDATE cultural_knowledge SET title='Kết cấu năm thân',content='Áo được ghép từ hai thân trước, hai thân sau và một thân con phía trong. Áo có năm khuy; kiểu tay chẽn có ống tay gọn. Phom nam và nữ có một số khác biệt.',source_name='Cổng du lịch Huế – Sở Văn hóa, Thể thao và Du lịch – Tinh tế áo dài ngũ thân',source_url='https://visithue.vn/Tinh-te-ao-dai-ngu-than.html/?pid=MjA1MjR8Y3NkbGRs0' WHERE outfit_id=(SELECT id FROM outfits WHERE code='AO_NGU_THAN') AND category='CHARACTERISTICS';
UPDATE outfits SET origin='Áo ngũ thân gắn với cải cách y phục của chúa Nguyễn Phúc Khoát năm 1744 tại Đàng Trong. Dưới thời Minh Mạng, trang phục được phổ biến trên phạm vi cả nước.',cultural_meaning='Theo nhà nghiên cứu Nguyễn Xuân Hoa, bốn thân chính được diễn giải tượng trưng cho cha mẹ hai bên, thân con cho người mặc. Năm khuy được liên hệ với ngũ thường và ngũ luân.' WHERE code='AO_NGU_THAN';
UPDATE cultural_rules SET source_name='Khám phá Huế – nghiên cứu của Nguyễn Xuân Hoa, nguồn Báo Thừa Thiên Huế – Giữ áo dài Nhật Bình cho Huế',source_url='https://khamphahue.com.vn/Du-lich/Chi-tiet/tid/Giu-ao-dai-Nhat-Binh-cho-Hue.html/pid/10926/cid/28',source_note='Nguồn giới thiệu lịch sử và đặc trưng trang phục. Gợi ý phối đồ và điểm số là quy tắc tham khảo của ứng dụng, chưa được nguồn này xác nhận toàn bộ.',source_verified=FALSE WHERE outfit_id=(SELECT id FROM outfits WHERE code='NHAT_BINH');
UPDATE cultural_knowledge SET title='Nhật Bình trong triều Nguyễn',content='Theo nghiên cứu của Nguyễn Xuân Hoa, Nhật Bình được quy định trong nội cung từ thời Gia Long. Vai trò triều phục hay thường phục thay đổi theo phẩm cấp, không phải mọi người đều dùng giống nhau.',source_name='Khám phá Huế – nghiên cứu của Nguyễn Xuân Hoa, nguồn Báo Thừa Thiên Huế – Giữ áo dài Nhật Bình cho Huế',source_url='https://khamphahue.com.vn/Du-lich/Chi-tiet/tid/Giu-ao-dai-Nhat-Binh-cho-Hue.html/pid/10926/cid/28' WHERE outfit_id=(SELECT id FROM outfits WHERE code='NHAT_BINH') AND category='ORIGIN';
UPDATE cultural_knowledge SET title='Phẩm cấp và bảo tồn',content='Màu sắc Nhật Bình từng dùng để phân biệt phẩm trật. Trang phục về sau xuất hiện trong cưới hỏi và lễ nghi dân gian ở Huế; ngày nay có hoạt động phục dựng, bảo tồn.',source_name='Khám phá Huế – nghiên cứu của Nguyễn Xuân Hoa, nguồn Báo Thừa Thiên Huế – Giữ áo dài Nhật Bình cho Huế',source_url='https://khamphahue.com.vn/Du-lich/Chi-tiet/tid/Giu-ao-dai-Nhat-Binh-cho-Hue.html/pid/10926/cid/28' WHERE outfit_id=(SELECT id FROM outfits WHERE code='NHAT_BINH') AND category='MEANING';
UPDATE cultural_knowledge SET title='Cổ áo và tay áo',content='Áo có cổ bản rộng tạo dáng chữ nhật trước ngực, mở giữa thân trước, thân rộng và tay rộng. Khăn vành là cách kết hợp được ghi nhận vào cuối thời Nguyễn.',source_name='Khám phá Huế – nghiên cứu của Nguyễn Xuân Hoa, nguồn Báo Thừa Thiên Huế – Giữ áo dài Nhật Bình cho Huế',source_url='https://khamphahue.com.vn/Du-lich/Chi-tiet/tid/Giu-ao-dai-Nhat-Binh-cho-Hue.html/pid/10926/cid/28' WHERE outfit_id=(SELECT id FROM outfits WHERE code='NHAT_BINH') AND category='CHARACTERISTICS';
UPDATE outfits SET origin='Theo nghiên cứu của Nguyễn Xuân Hoa, Nhật Bình được quy định trong nội cung từ thời Gia Long. Vai trò triều phục hay thường phục thay đổi theo phẩm cấp, không phải mọi người đều dùng giống nhau.',cultural_meaning='Màu sắc Nhật Bình từng dùng để phân biệt phẩm trật. Trang phục về sau xuất hiện trong cưới hỏi và lễ nghi dân gian ở Huế; ngày nay có hoạt động phục dựng, bảo tồn.' WHERE code='NHAT_BINH';
UPDATE cultural_rules SET source_name='Ủy ban Nhà nước về người Việt Nam ở nước ngoài – Áo bà ba – Trang phục của phụ nữ Nam Bộ',source_url='https://scov.gov.vn/ban-sac-van-hoa/huong-vi-que-nha/ao-ba-ba-trang-phuc-cua-phu-nu-nam-bo.html',source_note='Nguồn giới thiệu lịch sử và đặc trưng trang phục. Gợi ý phối đồ và điểm số là quy tắc tham khảo của ứng dụng, chưa được nguồn này xác nhận toàn bộ.',source_verified=FALSE WHERE outfit_id=(SELECT id FROM outfits WHERE code='AO_BA_BA');
UPDATE cultural_knowledge SET title='Trang phục gắn với Nam Bộ',content='Áo bà ba gắn với đời sống người dân Nam Bộ, đặc biệt ở vùng sông nước Cửu Long. Phần giới thiệu này không khẳng định một thời điểm ra đời duy nhất.',source_name='Ủy ban Nhà nước về người Việt Nam ở nước ngoài – Áo bà ba – Trang phục của phụ nữ Nam Bộ',source_url='https://scov.gov.vn/ban-sac-van-hoa/huong-vi-que-nha/ao-ba-ba-trang-phuc-cua-phu-nu-nam-bo.html' WHERE outfit_id=(SELECT id FROM outfits WHERE code='AO_BA_BA') AND category='ORIGIN';
UPDATE cultural_knowledge SET title='Nét mộc mạc phương Nam',content='Bài viết của Ủy ban Nhà nước về người Việt Nam ở nước ngoài giới thiệu áo bà ba như một hình ảnh gần gũi của phụ nữ Nam Bộ trong lao động và đời sống.',source_name='Ủy ban Nhà nước về người Việt Nam ở nước ngoài – Áo bà ba – Trang phục của phụ nữ Nam Bộ',source_url='https://scov.gov.vn/ban-sac-van-hoa/huong-vi-que-nha/ao-ba-ba-trang-phuc-cua-phu-nu-nam-bo.html' WHERE outfit_id=(SELECT id FROM outfits WHERE code='AO_BA_BA') AND category='MEANING';
UPDATE cultural_knowledge SET title='Kiểu áo tiện dụng',content='Dạng áo bà ba phổ biến có thân trước mở giữa để cài khuy, xẻ hai bên hông và có túi ở phía trước. Trang phục thường phối với quần; các kiểu cải tiến có cổ áo đa dạng.',source_name='Ủy ban Nhà nước về người Việt Nam ở nước ngoài – Áo bà ba – Trang phục của phụ nữ Nam Bộ',source_url='https://scov.gov.vn/ban-sac-van-hoa/huong-vi-que-nha/ao-ba-ba-trang-phuc-cua-phu-nu-nam-bo.html' WHERE outfit_id=(SELECT id FROM outfits WHERE code='AO_BA_BA') AND category='CHARACTERISTICS';
UPDATE outfits SET origin='Áo bà ba gắn với đời sống người dân Nam Bộ, đặc biệt ở vùng sông nước Cửu Long. Phần giới thiệu này không khẳng định một thời điểm ra đời duy nhất.',cultural_meaning='Bài viết của Ủy ban Nhà nước về người Việt Nam ở nước ngoài giới thiệu áo bà ba như một hình ảnh gần gũi của phụ nữ Nam Bộ trong lao động và đời sống.' WHERE code='AO_BA_BA';
INSERT INTO data_documents(data_key,source_path,sha256,payload) VALUES ('cultural.sources','migration:V11__accurate_cultural_sources','656dff6fcb6aa576fb6bac67a3c84e99c48fd14449d2261acc64b63938f91fbf',CAST('[{"id":"AO_DAI","title":"All about ao dai: Vietnam''s national dress","publisher":"Cục Du lịch Quốc gia Việt Nam – Vietnam Tourism","url":"https://vietnam.travel/things-to-do/ao-dai-vietnam","checkedAt":"2026-10-09","httpStatus":200},{"id":"AO_TU_THAN","title":"Nguồn gốc của Áo dài Việt Nam (phần 1)","publisher":"Hội LHPN tỉnh Khánh Hòa – nghiên cứu của Trịnh Bách","url":"https://hlhpn.khanhhoa.gov.vn/article/tin-tuc-su-kien/nguon-goc-cua-ao-dai-viet-nam-phan-1.html","checkedAt":"2026-10-09","httpStatus":200},{"id":"QUAN_HO","title":"Dân ca Quan họ Bắc Ninh","publisher":"Cục Di sản văn hóa","url":"https://dsvh.gov.vn/dan-ca-quan-ho-bac-ninh-482","checkedAt":"2026-10-09","httpStatus":200},{"id":"AO_NGU_THAN","title":"Tinh tế áo dài ngũ thân","publisher":"Cổng du lịch Huế – Sở Văn hóa, Thể thao và Du lịch","url":"https://visithue.vn/Tinh-te-ao-dai-ngu-than.html/?pid=MjA1MjR8Y3NkbGRs0","checkedAt":"2026-10-09","httpStatus":200},{"id":"NGU_THAN_HISTORY","title":"Lễ đón nhận danh hiệu Di sản văn hóa phi vật thể quốc gia “Tri thức may, mặc Áo dài Huế”","publisher":"Sở Văn hóa, Thể thao và Du lịch thành phố Huế","url":"https://svhttdl.hue.gov.vn/tin-trong-tinh/le-don-nhan-danh-hieu-di-san-van-hoa-phi-vat-the-quoc-gia-tri-thuc-may-mac-ao-dai-hue.html","checkedAt":"2026-10-09","httpStatus":200},{"id":"NHAT_BINH","title":"Giữ áo dài Nhật Bình cho Huế","publisher":"Khám phá Huế – nghiên cứu của Nguyễn Xuân Hoa, nguồn Báo Thừa Thiên Huế","url":"https://khamphahue.com.vn/Du-lich/Chi-tiet/tid/Giu-ao-dai-Nhat-Binh-cho-Hue.html/pid/10926/cid/28","checkedAt":"2026-10-09","httpStatus":200},{"id":"AO_BA_BA","title":"Áo bà ba – Trang phục của phụ nữ Nam Bộ","publisher":"Ủy ban Nhà nước về người Việt Nam ở nước ngoài","url":"https://scov.gov.vn/ban-sac-van-hoa/huong-vi-que-nha/ao-ba-ba-trang-phuc-cua-phu-nu-nam-bo.html","checkedAt":"2026-10-09","httpStatus":200}]' AS JSONB));
UPDATE ai_catalog_entries SET metadata=CAST('{"id":"CC_AO_DAI","garmentId":"ao_dai","title":"Áo dài","body":"Áo dài hiện đại phát triển từ áo ngũ thân. Trong thập niên 1930, họa sĩ Nguyễn Cát Tường (Le Mur) góp phần thay đổi phom áo theo hướng ôm dáng hơn. Áo dài hiện diện trong học đường, lễ Tết, cưới hỏi và chụp ảnh. Sắc trắng thường gắn với hình ảnh nữ sinh; sắc đỏ thường được chọn dịp Tết và lễ cưới. Áo dài thường mặc cùng quần. Các thiết kế đương đại có nhiều biến thể về chiều dài, tay áo và cổ áo, trong đó có cổ thuyền hoặc cổ tròn.","sources":["https://vietnam.travel/things-to-do/ao-dai-vietnam"],"verified":true}' AS JSONB) WHERE dataset_key='culture-cards' AND entry_key='CC_AO_DAI';
UPDATE ai_catalog_entries SET metadata=CAST('{"id":"CC_NGU_THAN","garmentId":"ao_ngu_than","title":"Áo ngũ thân","body":"Áo ngũ thân gắn với cải cách y phục của chúa Nguyễn Phúc Khoát năm 1744 tại Đàng Trong. Dưới thời Minh Mạng, trang phục được phổ biến trên phạm vi cả nước. Theo nhà nghiên cứu Nguyễn Xuân Hoa, bốn thân chính được diễn giải tượng trưng cho cha mẹ hai bên, thân con cho người mặc. Năm khuy được liên hệ với ngũ thường và ngũ luân. Áo được ghép từ hai thân trước, hai thân sau và một thân con phía trong. Áo có năm khuy; kiểu tay chẽn có ống tay gọn. Phom nam và nữ có một số khác biệt.","sources":["https://svhttdl.hue.gov.vn/tin-trong-tinh/le-don-nhan-danh-hieu-di-san-van-hoa-phi-vat-the-quoc-gia-tri-thuc-may-mac-ao-dai-hue.html","https://visithue.vn/Tinh-te-ao-dai-ngu-than.html/?pid=MjA1MjR8Y3NkbGRs0"],"verified":true}' AS JSONB) WHERE dataset_key='culture-cards' AND entry_key='CC_NGU_THAN';
UPDATE ai_catalog_entries SET metadata=CAST('{"id":"CC_TU_THAN","garmentId":"ao_tu_than","title":"Áo tứ thân","body":"Theo nghiên cứu của Trịnh Bách được Hội LHPN đăng tải, áo dài tứ thân từng gắn với phụ nữ nông thôn Bắc Bộ, thường mặc cùng yếm và váy. Trang phục liền chị Quan họ có áo mớ ba, mớ bảy và nón thúng quai thao. Đây là bối cảnh văn hóa Kinh Bắc để tìm hiểu cách phối trang phục lễ hội. Áo tứ thân có bốn thân, mở ở giữa phía trước và không có khuy cài theo dạng được mô tả trong nghiên cứu. Vạt áo có thể thắt hoặc buông, giữ bằng dây lưng vải.","sources":["https://hlhpn.khanhhoa.gov.vn/article/tin-tuc-su-kien/nguon-goc-cua-ao-dai-viet-nam-phan-1.html","https://dsvh.gov.vn/dan-ca-quan-ho-bac-ninh-482"],"verified":true}' AS JSONB) WHERE dataset_key='culture-cards' AND entry_key='CC_TU_THAN';
UPDATE ai_catalog_entries SET metadata=CAST('{"id":"CC_NHAT_BINH","garmentId":"nhat_binh","title":"Áo nhật bình","body":"Theo nghiên cứu của Nguyễn Xuân Hoa, Nhật Bình được quy định trong nội cung từ thời Gia Long. Vai trò triều phục hay thường phục thay đổi theo phẩm cấp, không phải mọi người đều dùng giống nhau. Màu sắc Nhật Bình từng dùng để phân biệt phẩm trật. Trang phục về sau xuất hiện trong cưới hỏi và lễ nghi dân gian ở Huế; ngày nay có hoạt động phục dựng, bảo tồn. Áo có cổ bản rộng tạo dáng chữ nhật trước ngực, mở giữa thân trước, thân rộng và tay rộng. Khăn vành là cách kết hợp được ghi nhận vào cuối thời Nguyễn.","sources":["https://khamphahue.com.vn/Du-lich/Chi-tiet/tid/Giu-ao-dai-Nhat-Binh-cho-Hue.html/pid/10926/cid/28"],"verified":true}' AS JSONB) WHERE dataset_key='culture-cards' AND entry_key='CC_NHAT_BINH';
UPDATE ai_catalog_entries SET metadata=CAST('{"id":"CC_BA_BA","garmentId":"ao_ba_ba","title":"Áo bà ba","body":"Áo bà ba gắn với đời sống người dân Nam Bộ, đặc biệt ở vùng sông nước Cửu Long. Phần giới thiệu này không khẳng định một thời điểm ra đời duy nhất. Bài viết của Ủy ban Nhà nước về người Việt Nam ở nước ngoài giới thiệu áo bà ba như một hình ảnh gần gũi của phụ nữ Nam Bộ trong lao động và đời sống. Dạng áo bà ba phổ biến có thân trước mở giữa để cài khuy, xẻ hai bên hông và có túi ở phía trước. Trang phục thường phối với quần; các kiểu cải tiến có cổ áo đa dạng.","sources":["https://scov.gov.vn/ban-sac-van-hoa/huong-vi-que-nha/ao-ba-ba-trang-phuc-cua-phu-nu-nam-bo.html"],"verified":true}' AS JSONB) WHERE dataset_key='culture-cards' AND entry_key='CC_BA_BA';
