UPDATE ai_cultural_rules SET metadata=CAST('{"id":"R01","level":"ok","criterion":"cau_truc","when":{"all":[{"garment":["ao_tu_than"]},{"hasAccessory":"non_quai_thao"}]},"reason":"Bộ trang phục gắn với vùng Kinh Bắc","suggestion":{"text":"Đội thêm khăn mỏ quạ bên dưới nón, đeo kiềng bạc để trọn bộ quan họ"},"sources":["https://dsvh.gov.vn/dan-ca-quan-ho-bac-ninh-482"],"verified":false,"sourceNote":"Nguồn giới thiệu lịch sử và đặc trưng trang phục. Gợi ý phối đồ và điểm số là quy tắc tham khảo của ứng dụng, chưa được nguồn này xác nhận toàn bộ."}' AS JSONB) WHERE rule_key='R01';
UPDATE ai_cultural_rules SET metadata=CAST('{"id":"R07","level":"consider","criterion":"cach_tan","when":{"all":[{"garment":["ao_ngu_than"]},{"hasAccessory":"sneaker"}]},"reason":"Cách tân chấp nhận được, nên giữ cổ đứng và 5 khuy","suggestion":{"text":"Chọn sneaker trắng trơn, giữ cổ đứng và đủ 5 khuy"},"sources":["https://visithue.vn/Tinh-te-ao-dai-ngu-than.html/?pid=MjA1MjR8Y3NkbGRs0"],"verified":false,"sourceNote":"Nguồn giới thiệu lịch sử và đặc trưng trang phục. Gợi ý phối đồ và điểm số là quy tắc tham khảo của ứng dụng, chưa được nguồn này xác nhận toàn bộ."}' AS JSONB) WHERE rule_key='R07';
UPDATE ai_cultural_rules SET metadata=CAST('{"id":"R12","level":"risk","criterion":"boi_canh","when":{"all":[{"occasion":["dam_cuoi","tet"]},{"allColorsIn":["trang_nga","trang_tinh"]},{"hasAccessory":"khan_van"}]},"reason":"Toàn màu trắng kèm khăn trắng gợi liên tưởng tang phục","suggestion":{"text":"Đổi màu chính sang đỏ son hoặc hồng đào","patch":{"colors":{"main":"do_son","bottom":"trang_nga"}}},"sources":[],"verified":false,"sourceNote":"Gợi ý phối đồ hoặc sử dụng của ứng dụng; chưa có nguồn đối chiếu cho nhận định này."}' AS JSONB) WHERE rule_key='R12';
UPDATE ai_cultural_rules SET metadata=CAST('{"id":"R15","level":"consider","criterion":"boi_canh","when":{"all":[{"garment":["nhat_binh"]},{"occasion":["dao_pho"]}]},"reason":"Vốn là lễ phục cung đình triều Nguyễn","suggestion":{"text":"Dạo phố nên chọn áo dài hoặc áo ngũ thân"},"sources":["https://khamphahue.com.vn/Du-lich/Chi-tiet/tid/Giu-ao-dai-Nhat-Binh-cho-Hue.html/pid/10926/cid/28"],"verified":false,"sourceNote":"Nguồn giới thiệu lịch sử và đặc trưng trang phục. Gợi ý phối đồ và điểm số là quy tắc tham khảo của ứng dụng, chưa được nguồn này xác nhận toàn bộ."}' AS JSONB) WHERE rule_key='R15';
UPDATE ai_cultural_rules SET metadata=CAST('{"id":"R20","level":"consider","criterion":"boi_canh","when":{"all":[{"weather":["mua"]},{"hasAccessory":"guoc"}]},"reason":"Trời mưa, guốc gỗ dễ trơn trượt và thấm nước","suggestion":{"text":"Đi giày kín mũi hoặc dép có đế bám thay cho guốc gỗ"},"sources":[],"verified":false,"sourceNote":"Gợi ý phối đồ hoặc sử dụng của ứng dụng; chưa có nguồn đối chiếu cho nhận định này."}' AS JSONB) WHERE rule_key='R20';
UPDATE ai_cultural_rules SET metadata=CAST('{"id":"R21","level":"consider","criterion":"boi_canh","when":{"all":[{"weather":["nang_nong"]},{"setting":["ngoai_troi","ca_hai"]},{"garment":["nhat_binh","ao_tu_than","ao_ngu_than"]}]},"reason":"Áo nhiều lớp, mặc lâu ngoài trời nắng nóng dễ bí và ra mồ hôi","suggestion":{"text":"Chọn áo dài hoặc áo bà ba vải mỏng, hoặc hẹn chụp lúc sáng sớm, chiều muộn"},"sources":[],"verified":false,"sourceNote":"Gợi ý phối đồ hoặc sử dụng của ứng dụng; chưa có nguồn đối chiếu cho nhận định này."}' AS JSONB) WHERE rule_key='R21';
UPDATE ai_cultural_rules SET metadata=CAST('{"id":"R22","level":"consider","criterion":"boi_canh","when":{"all":[{"weather":["nang_nong"]},{"setting":["ngoai_troi","ca_hai"]},{"mainColorIn":["den_tuyen","xanh_lam","nau_dat","tim_hue"]}]},"reason":"Màu tối hấp nắng, mặc ngoài trời lúc nắng nóng sẽ nóng hơn","suggestion":{"text":"Đổi màu chính sang màu sáng như trắng ngà hoặc be kem","patch":{"colors":{"main":"be_kem"}}},"sources":[],"verified":false,"sourceNote":"Gợi ý phối đồ hoặc sử dụng của ứng dụng; chưa có nguồn đối chiếu cho nhận định này."}' AS JSONB) WHERE rule_key='R22';
UPDATE ai_cultural_rules SET metadata=CAST('{"id":"R23","level":"ok","criterion":"boi_canh","when":{"all":[{"weather":["lanh"]},{"garment":["ao_ngu_than","nhat_binh","ao_tu_than"]}]},"reason":"Áo nhiều lớp, may dày, hợp với tiết trời se lạnh","suggestion":{"text":"Có thể mặc thêm áo lót giữ nhiệt bên trong"},"sources":[],"verified":false,"sourceNote":"Gợi ý phối đồ hoặc sử dụng của ứng dụng; chưa có nguồn đối chiếu cho nhận định này."}' AS JSONB) WHERE rule_key='R23';
UPDATE ai_cultural_rules SET metadata=CAST('{"id":"R24","level":"consider","criterion":"boi_canh","when":{"all":[{"weather":["mua"]},{"mainColorIn":["trang_nga","trang_tinh"]}]},"reason":"Áo màu trắng gặp mưa dễ ướt, lộ và bám bẩn","suggestion":{"text":"Chọn màu đậm hơn như hồng đào hoặc xanh lam","patch":{"colors":{"main":"hong_dao"}}},"sources":[],"verified":false,"sourceNote":"Gợi ý phối đồ hoặc sử dụng của ứng dụng; chưa có nguồn đối chiếu cho nhận định này."}' AS JSONB) WHERE rule_key='R24';
UPDATE ai_cultural_rules SET metadata=CAST('{"id":"R25","level":"consider","criterion":"boi_canh","when":{"all":[{"role":["khach"]},{"occasion":["dam_cuoi"]},{"garment":["nhat_binh"]}]},"reason":"Nhật bình là lễ phục rất trang trọng, khách dự cưới mặc dễ nổi bật hơn cô dâu","suggestion":{"text":"Khách nên chọn áo dài hoặc áo ngũ thân"},"sources":[],"verified":false,"sourceNote":"Gợi ý phối đồ hoặc sử dụng của ứng dụng; chưa có nguồn đối chiếu cho nhận định này."}' AS JSONB) WHERE rule_key='R25';
UPDATE ai_cultural_rules SET metadata=CAST('{"id":"R26","level":"consider","criterion":"boi_canh","when":{"all":[{"role":["khach"]},{"occasion":["dam_cuoi"]},{"mainColorIn":["do_son"]}]},"reason":"Màu đỏ thường dành cho cô dâu, khách mặc đỏ dễ trùng với nhân vật chính","suggestion":{"text":"Đổi sang hồng đào hoặc xanh lam","patch":{"colors":{"main":"hong_dao"}}},"sources":["https://vietnam.travel/things-to-do/ao-dai-vietnam"],"verified":false,"sourceNote":"Nguồn giới thiệu lịch sử và đặc trưng trang phục. Gợi ý phối đồ và điểm số là quy tắc tham khảo của ứng dụng, chưa được nguồn này xác nhận toàn bộ."}' AS JSONB) WHERE rule_key='R26';
UPDATE ai_cultural_rules SET metadata=CAST('{"id":"R27","level":"ok","criterion":"boi_canh","when":{"all":[{"role":["nhan_vat_chinh"]},{"occasion":["dam_cuoi"]},{"mainColorIn":["do_son","vang_hoang"]}]},"reason":"Đỏ và vàng là sắc màu quen thuộc của lễ cưới truyền thống","suggestion":{"text":"Có thể thêm khăn vấn cùng tông để trọn bộ"},"sources":[],"verified":false,"sourceNote":"Gợi ý phối đồ hoặc sử dụng của ứng dụng; chưa có nguồn đối chiếu cho nhận định này."}' AS JSONB) WHERE rule_key='R27';
UPDATE ai_cultural_rules SET metadata=CAST('{"id":"R28","level":"consider","criterion":"cach_tan","when":{"all":[{"occasion":["dam_cuoi","le_hoi_chua"]},{"pattern":["cham_bi","ke_soc"]},{"style":["truyen_thong"]}]},"reason":"Hoạ tiết chấm bi, kẻ sọc mang nét hiện đại, khác tinh thần truyền thống bạn chọn","suggestion":{"text":"Đổi sang vải trơn hoặc hoa văn tròn","patch":{"pattern":"hoa_van_tron"}},"sources":[],"verified":false,"sourceNote":"Gợi ý phối đồ hoặc sử dụng của ứng dụng; chưa có nguồn đối chiếu cho nhận định này."}' AS JSONB) WHERE rule_key='R28';
UPDATE ai_cultural_rules SET metadata=CAST('{"id":"R30","level":"ok","criterion":"cau_truc","when":{"all":[{"gender":["nam"]},{"garment":["ao_ngu_than","ao_dai"]},{"hasAccessory":"khan_xep"}]},"reason":"Khăn xếp đi cùng áo dài, áo ngũ thân là bộ lễ phục quen thuộc của nam giới","suggestion":{"text":"Chọn khăn cùng tông màu sẫm (đen, xanh lam) để tổng thể trang nhã"},"sources":["https://visithue.vn/Tinh-te-ao-dai-ngu-than.html/?pid=MjA1MjR8Y3NkbGRs0"],"verified":false,"sourceNote":"Nguồn giới thiệu lịch sử và đặc trưng trang phục. Gợi ý phối đồ và điểm số là quy tắc tham khảo của ứng dụng, chưa được nguồn này xác nhận toàn bộ."}' AS JSONB) WHERE rule_key='R30';
UPDATE ai_cultural_rules SET metadata=CAST('{"id":"R31","level":"consider","criterion":"phu_kien","when":{"all":[{"garment":["nhat_binh"]},{"any":[{"hasAccessory":"sneaker"},{"hasAccessory":"giay_bup_be"}]}]},"reason":"Nhật bình là lễ phục, giày hiện đại làm giảm vẻ trang trọng","suggestion":{"text":"Đổi sang hài thêu hoặc guốc gỗ"},"sources":["https://khamphahue.com.vn/Du-lich/Chi-tiet/tid/Giu-ao-dai-Nhat-Binh-cho-Hue.html/pid/10926/cid/28"],"verified":false,"sourceNote":"Nguồn giới thiệu lịch sử và đặc trưng trang phục. Gợi ý phối đồ và điểm số là quy tắc tham khảo của ứng dụng, chưa được nguồn này xác nhận toàn bộ."}' AS JSONB) WHERE rule_key='R31';
UPDATE ai_cultural_rules SET metadata=CAST('{"id":"R32","level":"ok","criterion":"phu_kien","when":{"all":[{"hasAccessory":"hai_theu"},{"any":[{"garment":["nhat_binh","ao_ngu_than"]},{"occasion":["dam_cuoi"]}]}]},"reason":"Hài thêu hợp với lễ phục và không khí lễ cưới","suggestion":{"text":"Chọn màu hài trùng màu điểm nhấn của khăn để đồng bộ"},"sources":[],"verified":false,"sourceNote":"Gợi ý phối đồ hoặc sử dụng của ứng dụng; chưa có nguồn đối chiếu cho nhận định này."}' AS JSONB) WHERE rule_key='R32';
UPDATE ai_cultural_rules SET metadata=CAST('{"id":"R33","level":"consider","criterion":"phu_kien","when":{"all":[{"hasAccessory":"non_quai_thao"},{"garment":["ao_dai","ao_ba_ba"]}]},"reason":"Nón quai thao gắn với áo tứ thân của liền chị quan họ, đi với áo dài hay bà ba dễ lệch tinh thần","suggestion":{"text":"Đổi sang nón lá, hoặc đổi áo sang áo tứ thân"},"sources":["https://dsvh.gov.vn/dan-ca-quan-ho-bac-ninh-482"],"verified":false,"sourceNote":"Nguồn giới thiệu lịch sử và đặc trưng trang phục. Gợi ý phối đồ và điểm số là quy tắc tham khảo của ứng dụng, chưa được nguồn này xác nhận toàn bộ."}' AS JSONB) WHERE rule_key='R33';
UPDATE ai_cultural_rules SET metadata=CAST('{"id":"R34","level":"ok","criterion":"phu_kien","when":{"all":[{"garment":["ao_tu_than"]},{"any":[{"hasAccessory":"khan_mo_qua"},{"hasAccessory":"kieng_bac"}]}]},"reason":"Khăn mỏ quạ, kiềng bạc là phụ kiện quen thuộc đi cùng áo tứ thân","suggestion":{"text":"Đi lễ hội có thể thêm nón quai thao; chụp ảnh trong nhà thì khăn mỏ quạ là đủ"},"sources":["https://dsvh.gov.vn/dan-ca-quan-ho-bac-ninh-482"],"verified":false,"sourceNote":"Nguồn giới thiệu lịch sử và đặc trưng trang phục. Gợi ý phối đồ và điểm số là quy tắc tham khảo của ứng dụng, chưa được nguồn này xác nhận toàn bộ."}' AS JSONB) WHERE rule_key='R34';
UPDATE ai_cultural_rules SET metadata=CAST('{"id":"R35","level":"consider","criterion":"boi_canh","when":{"all":[{"weather":["mua"]},{"hasAccessory":"quat_giay"}]},"reason":"Quạt giấy gặp mưa dễ ướt, rách","suggestion":{"text":"Thay bằng túi cói hoặc để quạt cho buổi chụp trong nhà"},"sources":[],"verified":false,"sourceNote":"Gợi ý phối đồ hoặc sử dụng của ứng dụng; chưa có nguồn đối chiếu cho nhận định này."}' AS JSONB) WHERE rule_key='R35';
UPDATE ai_cultural_rules SET metadata=CAST('{"id":"R36","level":"consider","criterion":"boi_canh","when":{"all":[{"role":["khach"]},{"occasion":["dam_cuoi"]},{"pattern":["phuong_hoang"]}]},"reason":"Phượng hoàng thường là hoạ tiết áo cưới của cô dâu, khách mặc dễ trùng nhân vật chính","suggestion":{"text":"Khách dự cưới nên chọn cành đào, sen hoặc hạc và mai","patch":{"pattern":"canh_dao"}},"sources":[],"verified":false,"sourceNote":"Gợi ý phối đồ hoặc sử dụng của ứng dụng; chưa có nguồn đối chiếu cho nhận định này."}' AS JSONB) WHERE rule_key='R36';
UPDATE ai_cultural_rules SET metadata=CAST('{"id":"R37","level":"ok","criterion":"dac_trung","when":{"all":[{"pattern":["sen","hoi_van","hac_mai"]},{"occasion":["le_hoi_chua","tet"]}]},"reason":"Sen, hồi văn, hạc và mai là hoạ tiết truyền thống, hợp không khí lễ hội, ngày Tết","suggestion":{"text":"Giữ nền trơn một màu để hoạ tiết nổi bật"},"sources":[],"verified":false,"sourceNote":"Gợi ý phối đồ hoặc sử dụng của ứng dụng; chưa có nguồn đối chiếu cho nhận định này."}' AS JSONB) WHERE rule_key='R37';
UPDATE ai_cultural_rules SET metadata=CAST('{"id":"R38","level":"ok","criterion":"dac_trung","when":{"all":[{"gender":["nam"]},{"pattern":["tung","truc","rong_may","song_nuoc"]}]},"reason":"Tùng, trúc, rồng, sóng nước là hoạ tiết quen thuộc trên áo nam, gợi khí chất vững vàng","suggestion":{"text":"Chọn nền xanh lam hoặc nâu đất để hoạ tiết vàng nổi bật"},"sources":[],"verified":false,"sourceNote":"Gợi ý phối đồ hoặc sử dụng của ứng dụng; chưa có nguồn đối chiếu cho nhận định này."}' AS JSONB) WHERE rule_key='R38';
UPDATE ai_cultural_rules SET metadata=CAST('{"id":"R39","level":"ok","criterion":"dac_trung","when":{"all":[{"pattern":["mai_vang","canh_dao"]},{"occasion":["tet"]}]},"reason":"Mai vàng, hoa đào là hoa ngày Tết, hợp không khí du xuân","suggestion":{"text":"Kết hợp khăn vấn hoặc khăn xếp cùng tông với hoa"},"sources":[],"verified":false,"sourceNote":"Gợi ý phối đồ hoặc sử dụng của ứng dụng; chưa có nguồn đối chiếu cho nhận định này."}' AS JSONB) WHERE rule_key='R39';
